function testSignupCta() {
  const cta = read("src/components/listens/ListenSignupCta.tsx");
  const page = read("src/app/(platform)/(listener)/listens/[slug]/page.tsx");
  const css = read("src/app/globals.css");

  assert(cta.includes("Создайте бесплатный аккаунт в АудиоЛаде"), "headline verbatim");
  assert(
    cta.includes("Сохраняйте любимые практики, слушайте медитации и музыку в одном"),
    "supporting text verbatim",
  );
  assert(cta.includes("Зарегистрироваться бесплатно"), "primary label");
  assert(cta.includes('href="/auth/sign-up"'), "primary href");
  assert(cta.includes("Открыть аудиотеку →"), "secondary label");
  assert(cta.includes('href="/my-practices"'), "secondary href");
  assert(cta.includes("Сохраняйте. Слушайте. Наполняйтесь."), "chip verbatim");
  assert(cta.includes("home-primary-cta home-primary-cta--compact"), "reuses home CTA");
  assert(cta.includes("UserIcon"), "reuses UserIcon");
  assert(cta.includes('aria-hidden="true"'), "decorative cluster hidden");
  assert(!cta.includes(".gif"), "no GIF");
  assert(!cta.includes("<video"), "no video");
  assert(!cta.includes("loadPlaylistQueue"), "no playlist queue");
  assert(!cta.includes("handlePlayPause"), "no play behavior");
  assert(page.includes("createClient"), "listen page uses createClient");
  assert(page.includes("getUser()"), "listen page uses getUser");
  assert(page.includes("isAuthenticated={isAuthenticated}"), "passes isAuthenticated");
  assert(css.includes("@media (prefers-reduced-motion: reduce)"), "reduced motion exists");
  assert(css.includes(".listen-signup-cta__glow,"), "CTA animations disabled on reduce");

  const bookmarkMatches = cta.split(EIGHTEENTH_BOOKMARK_PHRASE).length - 1;
  assert(bookmarkMatches === 1, "bookmark phrase present once in ListenSignupCta");
  const bookmarkAt = cta.indexOf(EIGHTEENTH_BOOKMARK_PHRASE);
  const coversMapAt = cta.indexOf("DECORATIVE_COVERS.map");
  const cardOneAt = cta.indexOf("card--one");
  assert(bookmarkAt >= 0, "bookmark phrase found");
  assert(
    (coversMapAt >= 0 && bookmarkAt < coversMapAt) ||
      (cardOneAt >= 0 && bookmarkAt < cardOneAt),
    "bookmark phrase appears before the 3-card cluster",
  );
  const view = read("src/components/listens/ListenPageView.tsx");
  assert(
    view.includes("{!isAuthenticated ? <ListenSignupCta /> : null}"),
    "ListenPageView still guest-gates ListenSignupCta",
  );
  assert(!view.includes("data-listen-bookmark-cta"), "bookmark not rendered separately in ListenPageView");
  assert(!view.includes(EIGHTEENTH_BOOKMARK_PHRASE), "bookmark phrase not rendered separately in ListenPageView");
  const childContent = read("src/lib/seo/listens/content/shum-vody-dlya-detey.ts");
  assert(!childContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "child content file has no bookmark phrase");
  assert(!childContent.includes("🔖"), "child content file has no bookmark emoji");
  const whiteNoiseContent = read("src/lib/seo/listens/content/belyy-shum-vody-slushat-onlayn.ts");
  assert(!whiteNoiseContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "white-noise content file has no bookmark phrase");
  assert(!whiteNoiseContent.includes("🔖"), "white-noise content file has no bookmark emoji");
  const newbornContent = read("src/lib/seo/listens/content/shum-vody-dlya-novorozhdennyh.ts");
  assert(!newbornContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "newborn content file has no bookmark phrase");
  assert(!newbornContent.includes("🔖"), "newborn content file has no bookmark emoji");
  const sleepMusicContent = read("src/lib/seo/listens/content/muzyka-dlya-sna-slushat-onlayn.ts");
  assert(!sleepMusicContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "sleep-music content file has no bookmark phrase");
  assert(!sleepMusicContent.includes("🔖"), "sleep-music content file has no bookmark emoji");
  const soothingSleepMusicContent = read("src/lib/seo/listens/content/uspokaivayushchaya-muzyka-dlya-sna-slushat-onlayn.ts");
  assert(!soothingSleepMusicContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "soothing-sleep-music content file has no bookmark phrase");
  assert(!soothingSleepMusicContent.includes("🔖"), "soothing-sleep-music content file has no bookmark emoji");
  const sleepInducingMusicContent = read("src/lib/seo/listens/content/usyplyayushchaya-muzyka-dlya-sna-slushat-onlayn.ts");
  assert(!sleepInducingMusicContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "sleep-inducing-music content file has no bookmark phrase");
  assert(!sleepInducingMusicContent.includes("🔖"), "sleep-inducing-music content file has no bookmark emoji");
  const noLyricsSleepMusicContent = read("src/lib/seo/listens/content/muzyka-dlya-sna-bez-slov-slushat-onlayn.ts");
  assert(!noLyricsSleepMusicContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "no-lyrics-sleep-music content file has no bookmark phrase");
  assert(!noLyricsSleepMusicContent.includes("🔖"), "no-lyrics-sleep-music content file has no bookmark emoji");
  const sleepMeditationContent = read("src/lib/seo/listens/content/meditatsiya-dlya-sna-slushat-onlayn-besplatno.ts");
  assert(!sleepMeditationContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "sleep-meditation content file has no bookmark phrase");
  assert(!sleepMeditationContent.includes("🔖"), "sleep-meditation content file has no bookmark emoji");
  const preSleepMeditationContent = read("src/lib/seo/listens/content/meditatsiya-pered-snom-slushat-onlayn-besplatno.ts");
  assert(!preSleepMeditationContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "pre-sleep-meditation content file has no bookmark phrase");
  assert(!preSleepMeditationContent.includes("🔖"), "pre-sleep-meditation content file has no bookmark emoji");
  const voiceSleepMeditationContent = read("src/lib/seo/listens/content/meditatsiya-dlya-sna-s-golosom-slushat-besplatno.ts");
  assert(!voiceSleepMeditationContent.includes(EIGHTEENTH_BOOKMARK_PHRASE), "voice-sleep-meditation content file has no bookmark phrase");
  assert(!voiceSleepMeditationContent.includes("🔖"), "voice-sleep-meditation content file has no bookmark emoji");
  assert(cta.includes('data-listen-signup-cta'), "section keeps data-listen-signup-cta");
  assert(cta.includes("data-listen-bookmark-cta"), "bookmark has data attribute");
}

