  assert(!contentSource.includes("[ДАЛЕЕ"), "forty-eighth content file has no [ДАЛЕЕ");
  assert(!contentSource.includes("🔖"), "forty-eighth content file has no bookmark emoji");
  assert(!contentSource.includes(EIGHTEENTH_BOOKMARK_PHRASE), "forty-eighth content file has no bookmark phrase");
  assert(!contentSource.includes("primaryPractice"), "forty-eighth content file has no primaryPractice");
  assert(!contentSource.includes("CreatorPathsCta"), "forty-eighth content file has no CreatorPathsCta");
  assert(!contentSource.includes("ListenSignupCta"), "forty-eighth content file does not edit ListenSignupCta");
  assert(contentSource.includes(FORTY_EIGHTH_REQUIRED_H2_A), "forty-eighth content file has required H2 A");
  assert(contentSource.includes(FORTY_EIGHTH_REQUIRED_H2_B), "forty-eighth content file has required H2 B");
  assert(contentSource.includes(FORTY_EIGHTH_REQUIRED_H2_C), "forty-eighth content file has required H2 C");
  assert(contentSource.includes(FORTY_EIGHTH_REQUIRED_FAQ), "forty-eighth content file has required FAQ");
  assert((contentSource.match(/href:/g) || []).length === 4, "forty-eighth content file has exactly four hrefs");
  assert(contentSource.includes(FORTY_EIGHTH_HREF_HUB), "forty-eighth content file has hub href");
  assert(contentSource.includes(FORTY_EIGHTH_HREF_3), "forty-eighth content file has calm-sleep href");
  assert(contentSource.includes(FORTY_EIGHTH_HREF_4), "forty-eighth content file has stress-relief href");
  assert(contentSource.includes(FORTY_EIGHTH_HREF_5), "forty-eighth content file has no-lyrics href");
  assert(!contentSource.includes("/topics/"), "forty-eighth content file has no topic hub hrefs");
  assert(!contentSource.includes("uspokaivayushchaya"), "forty-eighth content file has no uspokaivayushchaya href");
  assert(!contentSource.includes("muzyka-dlya-sna-i-meditacii-slushat-onlayn"), "forty-eighth content file has no sleep-meditation href");
  assert(!contentSource.includes("practice-player"), "forty-eighth content file has no practice-player");
  assert(!contentSource.includes("primaryPractice"), "forty-eighth content file has no primaryPractice twice");
  assert(!contentSource.includes("Studio"), "forty-eighth content file has no Studio");
  assert(!contentSource.includes("School"), "forty-eighth content file has no School");

  const slugs = listListenPageDefinitions().map((page) => page.slug);
  assert(slugs.includes(FORTY_EIGHTH_PAGE_SLUG), "registry contains forty-eighth listen slug");
  assert(slugs.includes(FORTY_SEVENTH_PAGE_SLUG), "registry still contains forty-seventh listen slug");
  assert(slugs.length === 73, "registry contains all 73 listen slugs");
  assert(new Set(slugs).size === slugs.length, "listen slugs stay unique");
  assert(
    RASSLABLYAYUSHCHAYA_MUZYKA_DLYA_SNA_SLUSHAT_ONLAYN_PAGE.playlistSlug === FORTY_EIGHTH_PLAYLIST_SLUG,
    "forty-eighth page playlistSlug is relaks-muzyka-dlya-sna",
  );
  assert(Boolean(getListenPageBySlug(FORTY_EIGHTH_PAGE_SLUG)), "new slug resolves");
  assert(!Boolean(getListenPageBySlug(FORTY_EIGHTH_PAGE_SLUG).topicSlug), "no extra fields leak");
  assert(Boolean(getListenPageBySlug("spokoynaya-muzyka-dlya-sna-slushat-onlayn")), "calm neighbor is registered as forty-ninth page");

  const sitemap = mapListenPageDefinitionsToSitemapEntries(undefined, "https://audiolad.ru");
  const sitemapUrls = sitemap.map((entry) => entry.url);
  assert(
    sitemapUrls.filter((url) => url === `https://audiolad.ru/listens/${FORTY_EIGHTH_PAGE_SLUG}`).length === 1,
    "sitemap contains forty-eighth listen canonical exactly once",
  );
  assert(
    sitemapUrls.filter((url) => url === `https://audiolad.ru/listens/${FORTY_SEVENTH_PAGE_SLUG}`).length === 1,
    "sitemap still contains forty-seventh listen canonical exactly once",
  );

  const data = resolveListenPageFromPlaylist({
    definition: RASSLABLYAYUSHCHAYA_MUZYKA_DLYA_SNA_SLUSHAT_ONLAYN_PAGE,
    loaded: {
      ok: true,
      detail: makePlaylist({
        playlist: {
          slug: FORTY_EIGHTH_PLAYLIST_SLUG,
          title: "Релакс музыка для сна | Расслабляющая музыка для сна",
        },
      }),
    },
  });
  assert(data, "forty-eighth page resolves against relaks playlist");
  assert(data.playlist.playlist.slug === FORTY_EIGHTH_PLAYLIST_SLUG, "resolved playlist slug is relaks-muzyka-dlya-sna");
  assert(data.path === `/listens/${FORTY_EIGHTH_PAGE_SLUG}`, "forty-eighth path");
  assert(
    data.canonicalUrl === `https://audiolad.ru/listens/${FORTY_EIGHTH_PAGE_SLUG}`,
    "forty-eighth canonical",
  );
  const graph = buildListenPageJsonLdGraph(data, "https://audiolad.ru");
  const serialized = JSON.stringify(graph);
  assert(serialized.includes('"Article"'), "forty-eighth JSON-LD Article");
  assert(serialized.includes('"WebPage"'), "forty-eighth JSON-LD WebPage");
  assert(serialized.includes('"Organization"'), "forty-eighth JSON-LD Organization");
  assert(serialized.includes('"BreadcrumbList"'), "forty-eighth JSON-LD BreadcrumbList");
  assert(serialized.includes('"ItemList"'), "forty-eighth JSON-LD ItemList");
  assert(serialized.includes('"FAQPage"'), "forty-eighth JSON-LD FAQPage");
  assert(!serialized.includes("MusicPlaylist"), "forty-eighth JSON-LD no MusicPlaylist");
  assert(!serialized.includes("AudioObject"), "forty-eighth JSON-LD no AudioObject");
  assert(!serialized.includes("primaryPractice"), "forty-eighth JSON-LD no primaryPractice");
  assert(!serialized.includes("Medical"), "forty-eighth JSON-LD no medical schema");
  assert(!serialized.includes(EIGHTEENTH_BOOKMARK_PHRASE), "forty-eighth JSON-LD has no bookmark phrase");
  assert(!serialized.includes("🔖"), "forty-eighth JSON-LD has no bookmark emoji");
