const SIXTIETH_FORBIDDEN_HREFS = [
  "/listens/taro-privlechenie-deneg",
  "/listens/karta-taro-dlya-privlecheniya-deneg",
  "/listens/taro-na-dengi-na-zastavku-telefona",
  "/listens/taro-bogatstva-i-dengi",
  "/listens/taro-bolshih-deneg",
];

function testSixtiethPage() {
  const parsed = parseListenPageDefinition(RASKLAD_TARO_NA_DENGI_PAGE);
  assert(parsed.ok, "sixtieth production definition valid");
  assert(parsed.definition.slug === SIXTIETH_PAGE_SLUG, "sixtieth page slug");
  assert(parsed.definition.playlistSlug === SIXTIETH_PLAYLIST_SLUG, "sixtieth playlistSlug exact");
  assert(parsed.definition.h1 === SIXTIETH_PAGE_H1, "sixtieth h1 exact");
  assert(parsed.definition.title === SIXTIETH_PAGE_TITLE, "sixtieth title is TZ Meta Title");
  assert(
    parsed.definition.description === SIXTIETH_PAGE_DESCRIPTION,
    "sixtieth description equals TZ meta string",
  );
  assert(parsed.definition.indexable === true, "sixtieth is indexable");
  assert(parsed.definition.type === "listen", "sixtieth type is listen");
  assert(parsed.definition.intro.length === 3, "sixtieth page has three intro paragraphs");
  assert(
    parsed.definition.intro[0] === SIXTIETH_EXPECTED_INTRO[0] &&
      parsed.definition.intro[1] === SIXTIETH_EXPECTED_INTRO[1] &&
      parsed.definition.intro[2] === SIXTIETH_EXPECTED_INTRO[2],
    "sixtieth intro[0..2] verbatim",
  );
  assert(parsed.definition.sections.length === 12, "sixtieth page has 12 sections");
  assert(
    parsed.definition.sections.map((section) => section.title).join("\n") ===
      SIXTIETH_EXPECTED_SECTION_TITLES.join("\n"),
    "sixtieth page 12 section titles verbatim",
  );
  assert(parsed.definition.faq.length === 8, "sixtieth page has 8 FAQ items");
  assert(
    parsed.definition.faq.every(
      (item, index) =>
        item.question === SIXTIETH_EXPECTED_FAQ[index].question &&
        item.answer === SIXTIETH_EXPECTED_FAQ[index].answer,
    ),
    "sixtieth page 8 FAQ verbatim",
  );
  assert(!("internalLinks" in parsed.definition), "sixtieth page has no internalLinks");
  assert(!("cta" in parsed.definition), "sixtieth page has no cta");
  assert(!("topicSlug" in parsed.definition), "sixtieth page has no topicSlug");
  for (const key of FORBIDDEN_COMPOSITION_KEYS) {
    assert(!(key in parsed.definition), `sixtieth page has no static ${key}`);
  }

  const headings = parsed.definition.sections
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "heading");
  assert(headings.length === 14, "sixtieth page has exactly 14 H3s");
  assert(
    headings.every((block) => block.level === 3),
    "sixtieth H3s use level 3",
  );
  assert(
    headings.map((block) => block.title).join("\n") === SIXTIETH_EXPECTED_H3_TITLES.join("\n"),
    "sixtieth 14 H3 titles verbatim",
  );
  const schemaSection = parsed.definition.sections.find(
    (section) => section.title === "Простая схема расклада Таро на деньги",
  );
  assert(schemaSection, "sixtieth schema H2 present");
  const schemaHeadings = (schemaSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(schemaHeadings.length === 5, "sixtieth 5 H3s live inside schema H2");
  assert(
    schemaHeadings.map((block) => block.title).join("\n") === SIXTIETH_EXPECTED_H3_TITLES.slice(0, 5).join("\n"),
    "sixtieth schema H3 titles verbatim",
  );
  const stepsSection = parsed.definition.sections.find(
    (section) => section.title === "Как сделать расклад Таро на деньги пошагово",
  );
  assert(stepsSection, "sixtieth steps H2 present");
  const stepsHeadings = (stepsSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(stepsHeadings.length === 9, "sixtieth 9 H3s live inside steps H2");
  assert(
    stepsHeadings.map((block) => block.title).join("\n") === SIXTIETH_EXPECTED_H3_TITLES.slice(5).join("\n"),
    "sixtieth steps H3 titles verbatim",
  );
  const otherHeadings = parsed.definition.sections
    .filter((section) => section !== schemaSection && section !== stepsSection)
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "heading");
  assert(otherHeadings.length === 0, "sixtieth has no H3s outside schema and steps H2s");

  const allTextChunks = [
    parsed.definition.h1,
    parsed.definition.title,
    parsed.definition.description,
    ...parsed.definition.intro,
    ...parsed.definition.sections.flatMap((section) => [
      section.title,
      ...(section.paragraphs ?? []),
      ...(section.blocks ?? []).flatMap((block) => {
        if (block.kind === "paragraph") return [block.text];
        if (block.kind === "list") return block.items ?? [];
        if (block.kind === "rich_paragraph") {
          return (block.segments ?? []).map((segment) => segment.text ?? segment.label ?? "");
        }
        if (block.kind === "heading") return [block.title];
        return [];
      }),
    ]),
    ...parsed.definition.faq.flatMap((item) => [item.question, item.answer]),
  ].join("\n");

  assert(allTextChunks.includes(SIXTIETH_PLAYLIST_TITLE), "sixtieth visible text mentions playlist title");
  assert(!allTextChunks.includes("https://audiolad.ru"), "sixtieth definition has no raw audiolad.ru URL");
  assert(!allTextChunks.includes("https://"), "sixtieth visible text has no raw https URLs");
  assert(!allTextChunks.includes("/listens/"), "sixtieth visible text has no listen paths");
  assert(!allTextChunks.includes(EIGHTEENTH_BOOKMARK_PHRASE), "sixtieth definition has no bookmark phrase");
  assert(!allTextChunks.includes("🔖"), "sixtieth definition has no bookmark emoji");
  assert(!allTextChunks.includes("[ЗДЕСЬ ВСТАВЛЯЕТСЯ"), "sixtieth definition has no playlist placeholder");
  assert(!allTextChunks.includes("[PUBLIC PLAYLIST]"), "sixtieth definition has no playlist marker");
  assert(!allTextChunks.includes("[ДАЛЕЕ]"), "sixtieth definition has no next marker");
  assert(!allTextChunks.includes("SEO-самопроверка"), "sixtieth definition has no SEO-самопроверка");

  const allRich = parsed.definition.sections
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "rich_paragraph");
  const allLinks = allRich.flatMap((block) => (block.segments ?? []).filter((segment) => "href" in segment));
  assert(allLinks.length === 2, "sixtieth page has exactly two hrefs");
  assert(allLinks[0].href === "/listens/taro-dengi", "sixtieth first href is /listens/taro-dengi");
  assert(allLinks[0].label === "Таро и деньги", "sixtieth first href label is Таро и деньги");
  assert(allLinks[1].href === "/listens/karta-taro-na-dengi", "sixtieth second href is /listens/karta-taro-na-dengi");
  assert(allLinks[1].label === "значении карт Таро в денежных вопросах", "sixtieth second href label is значении карт Таро в денежных вопросах");
  for (const href of SIXTIETH_FORBIDDEN_HREFS) {
    assert(!allLinks.some((link) => link.href === href), `sixtieth has no ${href} href`);
  }

  const contentSource = read("src/lib/seo/listens/content/rasklad-taro-na-dengi.ts");
  assert(!contentSource.includes("https://audiolad.ru"), "sixtieth content file has no raw audiolad.ru URL");
  assert(!contentSource.includes("https://"), "sixtieth content file has no https://");
  assert(contentSource.includes('href: "/listens/taro-dengi"'), "sixtieth content file has taro-dengi href");
  assert(contentSource.includes('label: "Таро и деньги"'), "sixtieth content file has Таро и деньги label");
  assert(contentSource.includes('href: "/listens/karta-taro-na-dengi"'), "sixtieth content file has karta-taro-na-dengi href");
  assert(contentSource.includes('label: "значении карт Таро в денежных вопросах"'), "sixtieth content file has значении карт Таро в денежных вопросах label");
  for (const href of SIXTIETH_FORBIDDEN_HREFS) {
    assert(!contentSource.includes(href), `sixtieth content file has no ${href}`);
  }
  assert(!contentSource.includes("taro-privlechenie-deneg"), "sixtieth content file has no taro-privlechenie-deneg");
  assert(!contentSource.includes("karta-taro-dlya-privlecheniya-deneg"), "sixtieth content file has no karta-taro-dlya-privlecheniya-deneg");
  assert(!contentSource.includes("taro-na-dengi-na-zastavku-telefona"), "sixtieth content file has no taro-na-dengi-na-zastavku-telefona");
  assert(!contentSource.includes("taro-bogatstva-i-dengi"), "sixtieth content file has no taro-bogatstva-i-dengi");
  assert(!contentSource.includes("taro-bolshih-deneg"), "sixtieth content file has no taro-bolshih-deneg");
  assert(!contentSource.includes("ListenSignupCta"), "sixtieth content file does not edit ListenSignupCta");
  assert(!contentSource.includes("primaryPractice"), "sixtieth content file has no primaryPractice");
  assert(!contentSource.includes("practice-player"), "sixtieth content file has no practice-player");
  assert(!contentSource.includes("Studio"), "sixtieth content file has no Studio");
  assert(!contentSource.includes("School"), "sixtieth content file has no School");
  assert(!contentSource.includes("internalLinks"), "sixtieth content file has no internalLinks");
  assert(!contentSource.includes("topicSlug"), "sixtieth content file has no topicSlug");
  assert(!contentSource.includes(EIGHTEENTH_BOOKMARK_PHRASE), "sixtieth content file has no bookmark phrase");
  assert(!contentSource.includes("🔖"), "sixtieth content file has no bookmark emoji");
  assert(!contentSource.includes("SEO-самопроверка"), "sixtieth content file has no SEO-самопроверка");
  assert(!contentSource.includes("[PUBLIC PLAYLIST]"), "sixtieth content file has no playlist marker");
  assert(!contentSource.includes("[ДАЛЕЕ]"), "sixtieth content file has no next marker");

  const slugs = listListenPageDefinitions().map((page) => page.slug);
  assert(slugs.includes(SIXTIETH_PAGE_SLUG), "registry contains sixtieth listen slug");
  assert(slugs.includes(FIFTY_NINTH_PAGE_SLUG), "registry still contains fifty-ninth listen slug");
  assert(slugs.length === 73, "registry contains all 73 listen slugs");
  assert(new Set(slugs).size === slugs.length, "listen slugs stay unique");
  assert(Boolean(getListenPageBySlug(SIXTIETH_PAGE_SLUG)), "new slug resolves");
  assert(Boolean(getListenPageBySlug(FIFTY_NINTH_PAGE_SLUG)), "fifty-ninth neighbor stays registered");

  const sitemap = mapListenPageDefinitionsToSitemapEntries(undefined, "https://audiolad.ru");
  const sitemapUrls = sitemap.map((entry) => entry.url);
  assert(
    sitemapUrls.filter((url) => url === `https://audiolad.ru/listens/${SIXTIETH_PAGE_SLUG}`).length === 1,
    "sitemap contains sixtieth listen canonical exactly once",
  );

  const data = resolveListenPageFromPlaylist({
    definition: RASKLAD_TARO_NA_DENGI_PAGE,
    loaded: {
      ok: true,
      detail: makePlaylist({
        playlist: {
          slug: SIXTIETH_PLAYLIST_SLUG,
          title: SIXTIETH_PLAYLIST_TITLE,
        },
      }),
    },
  });
  assert(data, "sixtieth page resolves against taro money playlist");
  assert(data.playlist.playlist.slug === SIXTIETH_PLAYLIST_SLUG, "resolved playlist slug is taro-meditatsiya-na-dengi");
  assert(data.playlist.playlist.title === SIXTIETH_PLAYLIST_TITLE, "resolved playlist title is live title");
  assert(data.path === `/listens/${SIXTIETH_PAGE_SLUG}`, "sixtieth path");
  assert(
    data.canonicalUrl === `https://audiolad.ru/listens/${SIXTIETH_PAGE_SLUG}`,
    "sixtieth canonical",
  );
}



