  assert(cardsHeadings.length === 0, "sixty-second cards H2 has no card H3s");
  const otherHeadings = parsed.definition.sections
    .filter((section) => section !== answerSection && section !== afterSection)
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "heading");
  assert(otherHeadings.length === 0, "sixty-second has no H3s outside the two designated H2s");

  const uniqueTitles = parsed.definition.sections.map((section) => section.title);
  assert(uniqueTitles.includes("Если получение денег зависит от другого человека"), "sixty-second keeps depends-on-other scenario");
  assert(uniqueTitles.includes("Если ожидается возврат денег"), "sixty-second keeps money-return scenario");
  assert(uniqueTitles.includes("Если человек ждёт оплату за работу"), "sixty-second keeps work-payment scenario");
  assert(uniqueTitles.includes("«Будут ли сегодня деньги Таро»"), "sixty-second keeps today scenario");

  const allTextChunks = [
    parsed.definition.h1,
    parsed.definition.title,
    parsed.definition.description,
    ...parsed.definition.intro,
    ...parsed.definition.sections.flatMap((section) => [
      section.title,
      ...(section.paragraphs ?? []),
      ...(section.blocks ?? []).flatMap((block) => {
        if (block.kind === "paragraph") return [block.text];
        if (block.kind === "list") return block.items ?? [];
        if (block.kind === "rich_paragraph") {
          return (block.segments ?? []).map((segment) => segment.text ?? segment.label ?? "");
        }
        if (block.kind === "heading") return [block.title];
        return [];
      }),
    ]),
    ...parsed.definition.faq.flatMap((item) => [item.question, item.answer]),
  ].join("\n");

  assert(allTextChunks.includes(SIXTY_SECOND_PLAYLIST_TITLE), "sixty-second visible text mentions playlist title");
  assert(allTextChunks.includes("Пентакли"), "sixty-second mentions Пентакли in prose");
