function testSixtyFifthPage() {
  const parsed = parseListenPageDefinition(TARO_RABOTA_I_FINANSY_PAGE);
  assert(parsed.ok, "sixty-fifth production definition valid");
  assert(parsed.definition.slug === SIXTY_FIFTH_PAGE_SLUG, "sixty-fifth page slug");
  assert(parsed.definition.playlistSlug === SIXTY_FIFTH_PLAYLIST_SLUG, "sixty-fifth playlistSlug exact");
  assert(parsed.definition.h1 === SIXTY_FIFTH_PAGE_H1, "sixty-fifth h1 exact");
  assert(parsed.definition.title === SIXTY_FIFTH_PAGE_TITLE, "sixty-fifth title is TZ Meta Title");
  assert(
    parsed.definition.description === SIXTY_FIFTH_PAGE_DESCRIPTION,
    "sixty-fifth description equals TZ meta string",
  );
  assert(parsed.definition.indexable === true, "sixty-fifth is indexable");
  assert(parsed.definition.type === "listen", "sixty-fifth type is listen");
  assert(parsed.definition.intro.length === 3, "sixty-fifth page has three intro paragraphs");
  assert(
    parsed.definition.intro[0] === SIXTY_FIFTH_EXPECTED_INTRO[0] &&
      parsed.definition.intro[1] === SIXTY_FIFTH_EXPECTED_INTRO[1] &&
      parsed.definition.intro[2] === SIXTY_FIFTH_EXPECTED_INTRO[2],
    "sixty-fifth intro[0..2] verbatim",
  );
  assert(parsed.definition.sections.length === 14, "sixty-fifth page has 14 sections");
  assert(
    parsed.definition.sections.map((section) => section.title).join("\n") ===
      SIXTY_FIFTH_EXPECTED_SECTION_TITLES.join("\n"),
    "sixty-fifth page 14 section titles verbatim",
  );
  assert(parsed.definition.faq.length === 8, "sixty-fifth page has 8 FAQ items");
  assert(
    parsed.definition.faq.every(
      (item, index) =>
        item.question === SIXTY_FIFTH_EXPECTED_FAQ[index].question &&
        item.answer === SIXTY_FIFTH_EXPECTED_FAQ[index].answer,
    ),
    "sixty-fifth page 8 FAQ verbatim",
  );
  assert(!("internalLinks" in parsed.definition), "sixty-fifth page has no internalLinks");
  assert(!("cta" in parsed.definition), "sixty-fifth page has no cta");
  assert(!("topicSlug" in parsed.definition), "sixty-fifth page has no topicSlug");
  for (const key of FORBIDDEN_COMPOSITION_KEYS) {
    assert(!(key in parsed.definition), `sixty-fifth page has no static ${key}`);
  }

  const headings = parsed.definition.sections
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "heading");
  assert(headings.length === 18, "sixty-fifth page has exactly 18 H3s");
  assert(
    headings.every((block) => block.level === 3),
    "sixty-fifth H3s use level 3",
  );
  assert(
    headings.map((block) => block.title).join("\n") === SIXTY_FIFTH_EXPECTED_H3_TITLES.join("\n"),
    "sixty-fifth 18 H3 titles verbatim",
  );
  const kartaSection = parsed.definition.sections.find(
    (section) => section.title === "Карты Таро в теме работы и финансов",
  );
  assert(kartaSection, "sixty-fifth card-meaning H2 present");
  const kartaHeadings = (kartaSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(kartaHeadings.length === 4, "sixty-fifth 4 H3s live inside card-meaning H2");
  assert(
    kartaHeadings.map((block) => block.title).join("\n") === SIXTY_FIFTH_KARTA_H3S.join("\n"),
    "sixty-fifth card-meaning H3 titles verbatim",
  );
  assert(kartaHeadings.every((block) => block.title !== "Десятка Пентаклей"), "sixty-fifth has no Ten of Pentacles H3");
  assert(kartaHeadings.every((block) => block.title !== "Колесо Фортуны"), "sixty-fifth has no Wheel of Fortune H3");
  assert(kartaHeadings.every((block) => block.title !== "Девятка Пентаклей"), "sixty-fifth has no Nine of Pentacles H3");
  const raskladSection = parsed.definition.sections.find(
    (section) => section.title === "Расклад Таро на работу и финансы",
  );
  assert(raskladSection, "sixty-fifth 5-card H2 present");
  const raskladHeadings = (raskladSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(raskladHeadings.length === 5, "sixty-fifth 5 H3s live inside 5-card H2");
  assert(
    raskladHeadings.map((block) => block.title).join("\n") === SIXTY_FIFTH_RASKLAD_H3S.join("\n"),
    "sixty-fifth 5-card H3 titles verbatim",
  );
  const perspectiveSection = parsed.definition.sections.find(
    (section) => section.title === "Как смотреть на финансовые перспективы текущей работы",
  );
  assert(perspectiveSection, "sixty-fifth perspective H2 present");
  const perspectiveHeadings = (perspectiveSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(perspectiveHeadings.length === 4, "sixty-fifth 4 H3s live inside perspective H2");
  assert(
    perspectiveHeadings.map((block) => block.title).join("\n") === SIXTY_FIFTH_PERSPECTIVE_H3S.join("\n"),
    "sixty-fifth perspective H3 titles verbatim",
  );
  const actionSection = parsed.definition.sections.find(
    (section) => section.title === "От карт к реальным действиям",
  );
  assert(actionSection, "sixty-fifth action H2 present");
  const actionHeadings = (actionSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(actionHeadings.length === 5, "sixty-fifth 5 H3s live inside action H2");
  assert(
    actionHeadings.map((block) => block.title).join("\n") === SIXTY_FIFTH_ACTION_H3S.join("\n"),
    "sixty-fifth action H3 titles verbatim",
  );
  assert(
    actionHeadings.every((block) => !/^\d+\.\s/.test(block.title)),
    "sixty-fifth action H3s have no leading numbers",
  );
  const otherHeadings = parsed.definition.sections
    .filter((section) => section !== kartaSection && section !== raskladSection && section !== perspectiveSection && section !== actionSection)
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "heading");
  assert(otherHeadings.length === 0, "sixty-fifth has no H3s outside the four designated H2s");

  const allTextChunks = [
    parsed.definition.h1,
    parsed.definition.title,
    parsed.definition.description,
    ...parsed.definition.intro,
    ...parsed.definition.sections.flatMap((section) => [
      section.title,
      ...(section.paragraphs ?? []),
      ...(section.blocks ?? []).flatMap((block) => {
        if (block.kind === "paragraph") return [block.text];
        if (block.kind === "list") return block.items ?? [];
        if (block.kind === "rich_paragraph") {
          return (block.segments ?? []).map((segment) => segment.text ?? segment.label ?? "");
        }
        if (block.kind === "heading") return [block.title];
        return [];
      }),
    ]),
    ...parsed.definition.faq.flatMap((item) => [item.question, item.answer]),
  ].join("\n");

  assert(allTextChunks.includes(SIXTY_FIFTH_PLAYLIST_TITLE), "sixty-fifth visible text mentions playlist title");
  assert(allTextChunks.includes("схему из пяти карт"), "sixty-fifth keeps unique 5-card work-finance scheme");
  assert(allTextChunks.includes("Восьмёрка Пентаклей"), "sixty-fifth keeps unique Eight of Pentacles");
  assert(allTextChunks.includes("Тройка Пентаклей"), "sixty-fifth keeps unique Three of Pentacles");
  assert(allTextChunks.includes("работа и финансы"), "sixty-fifth keeps work-and-finance stem");
  assert(allTextChunks.includes("ближайшее"), "sixty-fifth keeps nearest-term work-finance stem");
  assert(!allTextChunks.includes("Десятка Пентаклей"), "sixty-fifth has no named Ten of Pentacles");
  assert(!allTextChunks.includes("Колесо Фортуны"), "sixty-fifth has no Wheel of Fortune encyclopedia");
  assert(!allTextChunks.includes("https://audiolad.ru"), "sixty-fifth definition has no raw audiolad.ru URL");
  assert(!allTextChunks.includes("https://"), "sixty-fifth visible text has no raw https URLs");
  assert(!allTextChunks.includes("/listens/"), "sixty-fifth visible text has no listen paths");
  assert(!allTextChunks.includes(EIGHTEENTH_BOOKMARK_PHRASE), "sixty-fifth definition has no bookmark phrase");
  assert(!allTextChunks.includes("🔖"), "sixty-fifth definition has no bookmark emoji");
  assert(!allTextChunks.includes("[ЗДЕСЬ ВСТАВЛЯЕТСЯ"), "sixty-fifth definition has no playlist placeholder");
  assert(!allTextChunks.includes("[PUBLIC PLAYLIST]"), "sixty-fifth definition has no playlist marker");
  assert(!allTextChunks.includes("[ДАЛЕЕ]"), "sixty-fifth definition has no next marker");
  assert(!allTextChunks.includes("SEO-самопроверка"), "sixty-fifth definition has no SEO-самопроверка");

  const allRich = parsed.definition.sections
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "rich_paragraph");
  const allLinks = allRich.flatMap((block) => (block.segments ?? []).filter((segment) => "href" in segment));
  assert(allLinks.length === 3, "sixty-fifth page has exactly three hrefs");
  for (const [index, expected] of SIXTY_FIFTH_EXPECTED_LINKS.entries()) {
    assert(allLinks[index].href === expected.href, `sixty-fifth href[${index}] is ${expected.href}`);
    assert(allLinks[index].label === expected.label, `sixty-fifth label[${index}] is ${expected.label}`);
  }
  for (const href of SIXTY_FIFTH_FORBIDDEN_HREFS) {
    assert(!allLinks.some((link) => link.href === href), `sixty-fifth has no ${href} href`);
  }

  const contentSource = read("src/lib/seo/listens/content/taro-rabota-i-finansy.ts");
  assert(!contentSource.includes("https://audiolad.ru"), "sixty-fifth content file has no raw audiolad.ru URL");
  assert(!contentSource.includes("https://"), "sixty-fifth content file has no https://");
  for (const expected of SIXTY_FIFTH_EXPECTED_LINKS) {
    assert(contentSource.includes(`href: "${expected.href}"`), `sixty-fifth content file has ${expected.href}`);
    assert(contentSource.includes(`label: "${expected.label}"`), `sixty-fifth content file has ${expected.label} label`);
  }
  for (const href of SIXTY_FIFTH_FORBIDDEN_HREFS) {
    assert(!contentSource.includes(href), `sixty-fifth content file has no ${href}`);
  }
  assert(!contentSource.includes("ListenSignupCta"), "sixty-fifth content file does not edit ListenSignupCta");
  assert(!contentSource.includes("primaryPractice"), "sixty-fifth content file has no primaryPractice");
  assert(!contentSource.includes("practice-player"), "sixty-fifth content file has no practice-player");
  assert(!contentSource.includes("Studio"), "sixty-fifth content file has no Studio");
  assert(!contentSource.includes("School"), "sixty-fifth content file has no School");
  assert(!contentSource.includes("internalLinks"), "sixty-fifth content file has no internalLinks");
  assert(!contentSource.includes("topicSlug"), "sixty-fifth content file has no topicSlug");
  assert(!contentSource.includes(EIGHTEENTH_BOOKMARK_PHRASE), "sixty-fifth content file has no bookmark phrase");
  assert(!contentSource.includes("🔖"), "sixty-fifth content file has no bookmark emoji");
  assert(!contentSource.includes("SEO-самопроверка"), "sixty-fifth content file has no SEO-самопроверка");
  assert(!contentSource.includes("[PUBLIC PLAYLIST]"), "sixty-fifth content file has no playlist marker");
  assert(!contentSource.includes("[ДАЛЕЕ]"), "sixty-fifth content file has no next marker");

  const slugs = listListenPageDefinitions().map((page) => page.slug);
  assert(slugs.includes(SIXTY_FIFTH_PAGE_SLUG), "registry contains sixty-fifth listen slug");
  assert(slugs.includes(SIXTY_FOURTH_PAGE_SLUG), "registry still contains sixty-fourth listen slug");
  assert(slugs.length === 73, "registry contains all 73 listen slugs");
  assert(new Set(slugs).size === slugs.length, "listen slugs stay unique");
  assert(Boolean(getListenPageBySlug(SIXTY_FIFTH_PAGE_SLUG)), "new slug resolves");
  assert(Boolean(getListenPageBySlug(SIXTY_FOURTH_PAGE_SLUG)), "sixty-fourth neighbor stays registered");

  const sitemap = mapListenPageDefinitionsToSitemapEntries(undefined, "https://audiolad.ru");
  const sitemapUrls = sitemap.map((entry) => entry.url);
  assert(
    sitemapUrls.filter((url) => url === `https://audiolad.ru/listens/${SIXTY_FIFTH_PAGE_SLUG}`).length === 1,
    "sitemap contains sixty-fifth listen canonical exactly once",
  );

  const data = resolveListenPageFromPlaylist({
    definition: TARO_RABOTA_I_FINANSY_PAGE,
    loaded: {
      ok: true,
      detail: makePlaylist({
        playlist: {
          slug: SIXTY_FIFTH_PLAYLIST_SLUG,
          title: SIXTY_FIFTH_PLAYLIST_TITLE,
        },
      }),
    },
  });
  assert(data, "sixty-fifth page resolves against taro money playlist");
  assert(data.playlist.playlist.slug === SIXTY_FIFTH_PLAYLIST_SLUG, "resolved playlist slug is taro-meditatsiya-na-dengi");
  assert(data.playlist.playlist.title === SIXTY_FIFTH_PLAYLIST_TITLE, "resolved playlist title is live title");
  assert(data.path === `/listens/${SIXTY_FIFTH_PAGE_SLUG}`, "sixty-fifth path");
  assert(
    data.canonicalUrl === `https://audiolad.ru/listens/${SIXTY_FIFTH_PAGE_SLUG}`,
    "sixty-fifth canonical",
  );
}




