function testSixtyEighthPage() {
  const parsed = parseListenPageDefinition(RASKLAD_TARO_NA_RABOTU_PAGE);
  assert(parsed.ok, "sixty-eighth production definition valid");
  assert(parsed.definition.slug === SIXTY_EIGHTH_PAGE_SLUG, "sixty-eighth page slug");
  assert(parsed.definition.playlistSlug === SIXTY_EIGHTH_PLAYLIST_SLUG, "sixty-eighth playlistSlug exact");
  assert(parsed.definition.h1 === SIXTY_EIGHTH_PAGE_H1, "sixty-eighth h1 exact");
  assert(parsed.definition.title === SIXTY_EIGHTH_PAGE_TITLE, "sixty-eighth title is TZ Meta Title");
  assert(
    parsed.definition.description === SIXTY_EIGHTH_PAGE_DESCRIPTION,
    "sixty-eighth description equals TZ meta string",
  );
  assert(parsed.definition.indexable === true, "sixty-eighth is indexable");
  assert(parsed.definition.type === "listen", "sixty-eighth type is listen");
  assert(parsed.definition.intro.length === 3, "sixty-eighth page has three intro paragraphs");
  assert(
    parsed.definition.intro[0] === SIXTY_EIGHTH_EXPECTED_INTRO[0] &&
      parsed.definition.intro[1] === SIXTY_EIGHTH_EXPECTED_INTRO[1] &&
      parsed.definition.intro[2] === SIXTY_EIGHTH_EXPECTED_INTRO[2],
    "sixty-eighth intro[0..2] verbatim",
  );
  assert(parsed.definition.sections.length === 14, "sixty-eighth page has 14 sections");
  assert(
    parsed.definition.sections.map((section) => section.title).join("\n") ===
      SIXTY_EIGHTH_EXPECTED_SECTION_TITLES.join("\n"),
    "sixty-eighth page 14 section titles verbatim",
  );
  assert(parsed.definition.faq.length === 8, "sixty-eighth page has 8 FAQ items");
  assert(
    parsed.definition.faq.every(
      (item, index) =>
        item.question === SIXTY_EIGHTH_EXPECTED_FAQ[index].question &&
        item.answer === SIXTY_EIGHTH_EXPECTED_FAQ[index].answer,
    ),
    "sixty-eighth page 8 FAQ verbatim",
  );
  assert(!("internalLinks" in parsed.definition), "sixty-eighth page has no internalLinks");
  assert(!("cta" in parsed.definition), "sixty-eighth page has no cta");
  assert(!("topicSlug" in parsed.definition), "sixty-eighth page has no topicSlug");
  for (const key of FORBIDDEN_COMPOSITION_KEYS) {
    assert(!(key in parsed.definition), `sixty-eighth page has no static ${key}`);
  }

  const headings = parsed.definition.sections
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "heading");
  assert(headings.length === 29, "sixty-eighth page has exactly 29 H3s");
  assert(
    headings.every((block) => block.level === 3),
    "sixty-eighth H3s use level 3",
  );
  assert(
    headings.map((block) => block.title).join("\n") === SIXTY_EIGHTH_EXPECTED_H3_TITLES.join("\n"),
    "sixty-eighth 29 H3 titles verbatim",
  );
  const threeCardSection = parsed.definition.sections.find(
    (section) => section.title === "Таро на работу – расклад на 3 карты",
  );
  assert(threeCardSection, "sixty-eighth 3-card H2 present");
  const threeCardHeadings = (threeCardSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(threeCardHeadings.length === 3, "sixty-eighth 3 H3s live inside 3-card H2");
  assert(
    threeCardHeadings.map((block) => block.title).join("\n") === SIXTY_EIGHTH_THREE_CARD_H3S.join("\n"),
    "sixty-eighth 3-card H3 titles verbatim",
  );
  const fiveCardSection = parsed.definition.sections.find(
    (section) => section.title === "Расклад на работу Таро – схема на 5 карт",
  );
  assert(fiveCardSection, "sixty-eighth 5-card H2 present");
  const fiveCardHeadings = (fiveCardSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(fiveCardHeadings.length === 5, "sixty-eighth 5 H3s live inside 5-card H2");
  assert(
    fiveCardHeadings.map((block) => block.title).join("\n") === SIXTY_EIGHTH_FIVE_CARD_H3S.join("\n"),
    "sixty-eighth 5-card H3 titles verbatim",
  );
  const razborSection = parsed.definition.sections.find(
    (section) => section.title === "Как разбирать карты в раскладе",
  );
  assert(razborSection, "sixty-eighth razbor H2 present");
  const razborHeadings = (razborSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(razborHeadings.length === 5, "sixty-eighth 5 H3s live inside razbor H2");
  assert(
    razborHeadings.map((block) => block.title).join("\n") === SIXTY_EIGHTH_RAZBOR_H3S.join("\n"),
    "sixty-eighth razbor H3 titles verbatim",
  );
  assert(
    razborHeadings.every((block) => !/^\d+\.\s/.test(block.title)),
    "sixty-eighth razbor H3s have no leading numbers",
  );
  const exampleSection = parsed.definition.sections.find(
    (section) => section.title === "Пример разбора расклада Таро на работу",
  );
  assert(exampleSection, "sixty-eighth example H2 present");
  const exampleHeadings = (exampleSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(exampleHeadings.length === 5, "sixty-eighth 5 H3s live inside example H2");
  assert(
    exampleHeadings.map((block) => block.title).join("\n") === SIXTY_EIGHTH_EXAMPLE_H3S.join("\n"),
    "sixty-eighth example H3 titles verbatim",
  );
  const errorsSection = parsed.definition.sections.find(
    (section) => section.title === "Какие ошибки часто делают при раскладе на работу",
  );
  assert(errorsSection, "sixty-eighth errors H2 present");
  const errorsHeadings = (errorsSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(errorsHeadings.length === 6, "sixty-eighth 6 H3s live inside errors H2");
  assert(
    errorsHeadings.map((block) => block.title).join("\n") === SIXTY_EIGHTH_ERRORS_H3S.join("\n"),
    "sixty-eighth errors H3 titles verbatim",
  );
  const actionSection = parsed.definition.sections.find(
    (section) => section.title === "Как перейти от расклада к реальному действию",
  );
  assert(actionSection, "sixty-eighth action H2 present");
  const actionHeadings = (actionSection.blocks ?? []).filter((block) => block.kind === "heading");
  assert(actionHeadings.length === 5, "sixty-eighth 5 H3s live inside action H2");
  assert(
    actionHeadings.map((block) => block.title).join("\n") === SIXTY_EIGHTH_ACTION_H3S.join("\n"),
    "sixty-eighth action H3 titles verbatim",
  );
  assert(
    actionHeadings.every((block) => !/^\d+\.\s/.test(block.title)),
    "sixty-eighth action H3s have no leading numbers",
  );
  const designated = new Set([threeCardSection, fiveCardSection, razborSection, exampleSection, errorsSection, actionSection]);
  const otherHeadings = parsed.definition.sections
    .filter((section) => !designated.has(section))
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "heading");
  assert(otherHeadings.length === 0, "sixty-eighth has no H3s outside the six designated H2s");

  const prepSection = parsed.definition.sections.find(
    (section) => section.title === "Как подготовиться к раскладу Таро на работу",
  );
  assert(prepSection, "sixty-eighth prep H2 present");
  const prepLinks = (prepSection.blocks ?? [])
    .filter((block) => block.kind === "rich_paragraph")
    .flatMap((block) => (block.segments ?? []).filter((segment) => "href" in segment));
  assert(prepLinks.length === 1, "sixty-eighth first href lives in the prep H2");
  assert(prepLinks[0].href === "/listens/taro-na-rabotu" && prepLinks[0].label === "Таро на работу", "sixty-eighth work hub link");

  const questionsSection = parsed.definition.sections.find(
    (section) => section.title === "Какие вопросы подходят для расклада на работу",
  );
  assert(questionsSection, "sixty-eighth questions H2 present");
  const questionsLinks = (questionsSection.blocks ?? [])
    .filter((block) => block.kind === "rich_paragraph")
    .flatMap((block) => (block.segments ?? []).filter((segment) => "href" in segment));
  assert(questionsLinks.length === 1, "sixty-eighth second href lives in the questions H2");
  assert(questionsLinks[0].href === "/listens/taro-rabota" && questionsLinks[0].label === "Таро про работу", "sixty-eighth work overview link");

  const moneySection = parsed.definition.sections.find(
    (section) => section.title === "Если главный вопрос связан не с работой, а с деньгами",
  );
  assert(moneySection, "sixty-eighth money H2 present");
  const moneyLinks = (moneySection.blocks ?? [])
    .filter((block) => block.kind === "rich_paragraph")
    .flatMap((block) => (block.segments ?? []).filter((segment) => "href" in segment));
  assert(moneyLinks.length === 2, "sixty-eighth remaining hrefs live in the money H2");
  assert(moneyLinks[0].href === "/listens/taro-rabota-i-finansy" && moneyLinks[0].label === "Таро работа и финансы", "sixty-eighth first money link");
  assert(moneyLinks[1].href === "/listens/taro-dohody" && moneyLinks[1].label === "Таро доходы", "sixty-eighth second money link");

  const allTextChunks = [
    parsed.definition.h1,
    parsed.definition.title,
    parsed.definition.description,
    ...parsed.definition.intro,
    ...parsed.definition.sections.flatMap((section) => [
      section.title,
      ...(section.paragraphs ?? []),
      ...(section.blocks ?? []).flatMap((block) => {
        if (block.kind === "paragraph") return [block.text];
        if (block.kind === "list") return block.items ?? [];
        if (block.kind === "rich_paragraph") {
          return (block.segments ?? []).map((segment) => segment.text ?? segment.label ?? "");
        }
        if (block.kind === "heading") return [block.title];
        return [];
      }),
    ]),
    ...parsed.definition.faq.flatMap((item) => [item.question, item.answer]),
  ].join("\n");

  assert(allTextChunks.includes(SIXTY_EIGHTH_PLAYLIST_TITLE), "sixty-eighth visible text mentions playlist title");
  assert(allTextChunks.includes("Это не медитация на работу"), "sixty-eighth keeps not-a-work-meditation line");
  assert(allTextChunks.includes("Восьмёрка Пентаклей"), "sixty-eighth keeps Eight of Pentacles");
  assert(allTextChunks.includes("Тройка Пентаклей"), "sixty-eighth keeps Three of Pentacles");
  assert(allTextChunks.includes("Император"), "sixty-eighth keeps Emperor");
  assert(allTextChunks.includes("Двойка Жезлов"), "sixty-eighth keeps Two of Wands");
  assert(allTextChunks.includes("Пятёрка Жезлов"), "sixty-eighth keeps Five of Wands example");
  assert(allTextChunks.includes("схема из пяти"), "sixty-eighth keeps 5-card scheme");
  assert(allTextChunks.includes("схемы из трёх"), "sixty-eighth keeps 3-card scheme");
  assert(allTextChunks.includes("онлайн"), "sixty-eighth keeps online block");
  assert(!allTextChunks.includes("три Таро на работу"), "sixty-eighth has no три Таро на работу phrase");
  assert(!allTextChunks.includes("Десятка Пентаклей"), "sixty-eighth has no named Ten of Pentacles");
  assert(!allTextChunks.includes("Колесо Фортуны"), "sixty-eighth has no Wheel of Fortune encyclopedia");
  assert(!allTextChunks.includes("https://audiolad.ru"), "sixty-eighth definition has no raw audiolad.ru URL");
  assert(!allTextChunks.includes("https://"), "sixty-eighth visible text has no raw https URLs");
  assert(!allTextChunks.includes("/listens/"), "sixty-eighth visible text has no listen paths");
  assert(!allTextChunks.includes(EIGHTEENTH_BOOKMARK_PHRASE), "sixty-eighth definition has no bookmark phrase");
  assert(!allTextChunks.includes("🔖"), "sixty-eighth definition has no bookmark emoji");
  assert(!allTextChunks.includes("[ЗДЕСЬ ВСТАВЛЯЕТСЯ"), "sixty-eighth definition has no playlist placeholder");
  assert(!allTextChunks.includes("[PUBLIC PLAYLIST]"), "sixty-eighth definition has no playlist marker");
  assert(!allTextChunks.includes("[ДАЛЕЕ]"), "sixty-eighth definition has no next marker");
  assert(!allTextChunks.includes("SEO-самопроверка"), "sixty-eighth definition has no SEO-самопроверка");

  const allRich = parsed.definition.sections
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "rich_paragraph");
  const allLinks = allRich.flatMap((block) => (block.segments ?? []).filter((segment) => "href" in segment));
  assert(allLinks.length === 4, "sixty-eighth page has exactly four hrefs");
  for (const [index, expected] of SIXTY_EIGHTH_EXPECTED_LINKS.entries()) {
    assert(allLinks[index].href === expected.href, `sixty-eighth href[${index}] is ${expected.href}`);
    assert(allLinks[index].label === expected.label, `sixty-eighth label[${index}] is ${expected.label}`);
  }
  for (const href of SIXTY_EIGHTH_FORBIDDEN_HREFS) {
    assert(!allLinks.some((link) => link.href === href), `sixty-eighth has no ${href} href`);
  }

  const contentSource = read("src/lib/seo/listens/content/rasklad-taro-na-rabotu.ts");
  assert(!contentSource.includes("https://audiolad.ru"), "sixty-eighth content file has no raw audiolad.ru URL");
  assert(!contentSource.includes("https://"), "sixty-eighth content file has no https://");
  for (const expected of SIXTY_EIGHTH_EXPECTED_LINKS) {
    assert(contentSource.includes(`href: "${expected.href}"`), `sixty-eighth content file has ${expected.href}`);
    assert(contentSource.includes(`label: "${expected.label}"`), `sixty-eighth content file has ${expected.label} label`);
  }
  for (const href of SIXTY_EIGHTH_FORBIDDEN_HREFS) {
    assert(!contentSource.includes(href), `sixty-eighth content file has no ${href}`);
  }
  assert(!contentSource.includes("ListenSignupCta"), "sixty-eighth content file does not edit ListenSignupCta");
  assert(!contentSource.includes("primaryPractice"), "sixty-eighth content file has no primaryPractice");
  assert(!contentSource.includes("practice-player"), "sixty-eighth content file has no practice-player");
  assert(!contentSource.includes("Studio"), "sixty-eighth content file has no Studio");
  assert(!contentSource.includes("School"), "sixty-eighth content file has no School");
  assert(!contentSource.includes("internalLinks"), "sixty-eighth content file has no internalLinks");
  assert(!contentSource.includes("topicSlug"), "sixty-eighth content file has no topicSlug");
  assert(!contentSource.includes(EIGHTEENTH_BOOKMARK_PHRASE), "sixty-eighth content file has no bookmark phrase");
  assert(!contentSource.includes("🔖"), "sixty-eighth content file has no bookmark emoji");
  assert(!contentSource.includes("SEO-самопроверка"), "sixty-eighth content file has no SEO-самопроверка");
  assert(!contentSource.includes("[PUBLIC PLAYLIST]"), "sixty-eighth content file has no playlist marker");
  assert(!contentSource.includes("[ДАЛЕЕ]"), "sixty-eighth content file has no next marker");
  assert(!contentSource.includes("три Таро на работу"), "sixty-eighth content file has no три Таро на работу");

  const slugs = listListenPageDefinitions().map((page) => page.slug);
  assert(slugs.includes(SIXTY_EIGHTH_PAGE_SLUG), "registry contains sixty-eighth listen slug");
  assert(slugs.includes(SIXTY_SEVENTH_PAGE_SLUG), "registry still contains sixty-seventh listen slug");
  assert(slugs.length === 73, "registry contains all 73 listen slugs");
  assert(new Set(slugs).size === slugs.length, "listen slugs stay unique");
  assert(Boolean(getListenPageBySlug(SIXTY_EIGHTH_PAGE_SLUG)), "new slug resolves");
  assert(Boolean(getListenPageBySlug(SIXTY_SEVENTH_PAGE_SLUG)), "sixty-seventh neighbor stays registered");

  const sitemap = mapListenPageDefinitionsToSitemapEntries(undefined, "https://audiolad.ru");
  const sitemapUrls = sitemap.map((entry) => entry.url);
  assert(
    sitemapUrls.filter((url) => url === `https://audiolad.ru/listens/${SIXTY_EIGHTH_PAGE_SLUG}`).length === 1,
    "sitemap contains sixty-eighth listen canonical exactly once",
  );

  const data = resolveListenPageFromPlaylist({
    definition: RASKLAD_TARO_NA_RABOTU_PAGE,
    loaded: {
      ok: true,
      detail: makePlaylist({
        playlist: {
          slug: SIXTY_EIGHTH_PLAYLIST_SLUG,
          title: SIXTY_EIGHTH_PLAYLIST_TITLE,
        },
      }),
    },
  });
  assert(data, "sixty-eighth page resolves against taro money playlist");
  assert(data.playlist.playlist.slug === SIXTY_EIGHTH_PLAYLIST_SLUG, "resolved playlist slug is taro-meditatsiya-na-dengi");
  assert(data.playlist.playlist.title === SIXTY_EIGHTH_PLAYLIST_TITLE, "resolved playlist title is live title");
  assert(data.path === `/listens/${SIXTY_EIGHTH_PAGE_SLUG}`, "sixty-eighth path");
  assert(
    data.canonicalUrl === `https://audiolad.ru/listens/${SIXTY_EIGHTH_PAGE_SLUG}`,
    "sixty-eighth canonical",
  );
}




