  const allTextChunks = [
    parsed.definition.h1,
    parsed.definition.title,
    parsed.definition.description,
    ...parsed.definition.intro,
    ...parsed.definition.sections.flatMap((section) => [
      section.title,
      ...(section.paragraphs ?? []),
      ...(section.blocks ?? []).flatMap((block) => {
        if (block.kind === "paragraph") return [block.text];
        if (block.kind === "list") return block.items ?? [];
        if (block.kind === "rich_paragraph") {
          return (block.segments ?? []).map((segment) => segment.text ?? segment.label ?? "");
        }
        if (block.kind === "heading") return [block.title];
        return [];
      }),
    ]),
    ...parsed.definition.faq.flatMap((item) => [item.question, item.answer]),
  ].join("\n");

  assert(allTextChunks.includes(SEVENTY_FIRST_PLAYLIST_TITLE), "seventy-first visible text mentions playlist title");
  assert(allTextChunks.includes("Это не практика для получения работы"), "seventy-first keeps not-a-job-practice line");
  assert(allTextChunks.includes("Только по Таро – нет."), "seventy-first keeps explicit no-decision-by-tarot");
  assert(!allTextChunks.includes("https://audiolad.ru"), "seventy-first definition has no raw audiolad.ru URL");
  assert(!allTextChunks.includes("https://"), "seventy-first visible text has no raw https URLs");
  assert(!allTextChunks.includes("/listens/"), "seventy-first visible text has no listen paths");
  assert(!allTextChunks.includes(EIGHTEENTH_BOOKMARK_PHRASE), "seventy-first definition has no bookmark phrase");
