  const allRich = parsed.definition.sections
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "rich_paragraph");
  const allLinks = allRich.flatMap((block) => (block.segments ?? []).filter((segment) => "href" in segment));
  assert(allLinks.length === 5, "seventy-first page has exactly five hrefs");
  const uniqueDests = new Set(allLinks.map((link) => link.href));
  assert(uniqueDests.size === 4, "seventy-first page has exactly four unique dests");
  for (const [index, expected] of SEVENTY_FIRST_EXPECTED_LINKS.entries()) {
    assert(allLinks[index].href === expected.href, `seventy-first href[${index}] is ${expected.href}`);
    assert(allLinks[index].label === expected.label, `seventy-first label[${index}] is ${expected.label}`);
  }
