  for (const href of SEVENTY_FIRST_FORBIDDEN_HREFS) {
    assert(!allLinks.some((link) => link.href === href), `seventy-first has no ${href} href`);
  }

  const contentSource = read("src/lib/seo/listens/content/rasklad-taro-na-novuyu-rabotu.ts");
  assert(!contentSource.includes("https://audiolad.ru"), "seventy-first content file has no raw audiolad.ru URL");
  assert(!contentSource.includes("https://"), "seventy-first content file has no https://");
