  assert(!contentSource.includes("internalLinks"), "seventy-first content file has no internalLinks");
  assert(!contentSource.includes("topicSlug"), "seventy-first content file has no topicSlug");
  assert(!contentSource.includes(EIGHTEENTH_BOOKMARK_PHRASE), "seventy-first content file has no bookmark phrase");
  assert(!contentSource.includes("🔖"), "seventy-first content file has no bookmark emoji");
  assert(!contentSource.includes("SEO-самопроверка"), "seventy-first content file has no SEO-самопроверка");
